package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_prepend_TriageGen0Test {

    private Element element;

    @Before
    public void setUp() {
        element = new Element(Tag.valueOf("div"), "http://example.com");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testPrepend_NullHtml() {
        element.prepend(null);
    }

    @Test
    public void testPrepend_EmptyHtml() {
        element.prepend("");
        assertEquals("", element.html());
    }

    @Test
    public void testPrepend_SingleElement() {
        element.prepend("<p>Hello</p>");
        Elements children = element.children();
        assertEquals(1, children.size());
        assertEquals("p", children.first().tagName());
        assertEquals("Hello", children.first().text());
    }

    @Test
    public void testPrepend_MultipleElements() {
        element.prepend("<p>Hello</p><span>World</span>");
        Elements children = element.children();
        assertEquals(2, children.size());
        assertEquals("p", children.get(0).tagName());
        assertEquals("Hello", children.get(0).text());
        assertEquals("span", children.get(1).tagName());
        assertEquals("World", children.get(1).text());
    }

    @Test
    public void testPrepend_WithExistingChildren() {
        element.appendChild(new Element(Tag.valueOf("span"), "", new org.jsoup.nodes.Attributes(), "Existing"));
        element.prepend("<p>Hello</p>");
        Elements children = element.children();
        assertEquals(2, children.size());
        assertEquals("p", children.get(0).tagName());
        assertEquals("Hello", children.get(0).text());
        assertEquals("span", children.get(1).tagName());
        assertEquals("Existing", children.get(1).text());
    }

    @Test
    public void testPrepend_InvalidHtml() {
        element.prepend("<p>Unclosed tag");
        Elements children = element.children();
        assertEquals(1, children.size());
        assertEquals("p", children.first().tagName());
        assertEquals("Unclosed tag", children.first().text());
    }

    @Test
    public void testPrepend_NestedElements() {
        element.prepend("<div><p>Nested</p></div>");
        Elements children = element.children();
        assertEquals(1, children.size());
        assertEquals("div", children.first().tagName());
        Elements nestedChildren = children.first().children();
        assertEquals(1, nestedChildren.size());
        assertEquals("p", nestedChildren.first().tagName());
        assertEquals("Nested", nestedChildren.first().text());
    }

    @Test
    public void testPrepend_Attributes() {
        element.prepend("<a href='http://example.com'>Link</a>");
        Elements children = element.children();
        assertEquals(1, children.size());
        assertEquals("a", children.first().tagName());
        assertEquals("http://example.com", children.first().attr("href"));
        assertEquals("Link", children.first().text());
    }
}
